// TH14 v1.00b Extra 道中 w13：MainSub07 尾部 GirlA02 编队（st07.ecl.txt:962-972）
// 源 0962 wait(50) 起，16 轮各创建 ±140/-32 一对 GirlA02（共 32 只），轮间隔 15 帧。
// 每只按 GirlA02 0217-226 + GirlA02_at 0228-243 横切，GirlA02_at2 0245-264 每 10 帧发 5 路自机狙环。

const TIME_LIMIT: int = 1824;   // 120 开场 + 1700 排程/尾弹估计 + 4 启动余量
const OPENING_BUFFER: int = 120;

// 源 type8 = 米弹；TH14 映射目标同号，行基址 480（见 transcribe/th14/bullet-types.md）。
const TH14_RICE: int = 480;
const TH14_RICE_COLOR: int = 10;

// 源 GirlA02_at2 的 100 次 etOn/10f；每波 5 路整周自机狙环，速度为 4。
const VOLLEYS: int = 100;
const VOLLEY_FRAMES: int = 10;
const RING_WAYS: int = 5;

// 源 ANIM(a=1) 的出生退位移 -4*velocity，初速 4 → 16px，沿各弹自身角度回退。
const SPAWN_RETREAT: fx = 16fx;

async sub girl_a02_at2() {
    // 0247-0253：etNew/etAim(2)/etSprite(8,10)/etCount(5,1)/etAngle(0,3deg)/etSpeed(4,4)
    for v in 0..VOLLEYS {
        var aim: angle = aim_player();
        for i in 0..RING_WAYS {
            var a: angle = aim + ((i * 65536) / RING_WAYS) as angle;
            var bx: fx = $self_x - SPAWN_RETREAT * cos(a);
            var by: fx = $self_y - SPAWN_RETREAT * sin(a);
            _ = fire(TH14_RICE, TH14_RICE_COLOR, bx, by, 4fx, a, none, none);
        }
        // 0256-0262：A=100 的 do-while，每轮 etOn 后 wait(10)
        wait(VOLLEY_FRAMES);
    }
    // 源 at2 循环结束后 return；敌存活由主任务维持。
}

async sub girl_a02(mirror: int) {
    // 0219-0223 anmSelect/anmSetMain/drop* 按合成口径省略（纯表现/掉落）。
    // 0230-0231：源 setHurtbox(24,24)/setHitbox(16,16)，普通圆取第一值×0.5。
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 0232：@GirlA02_at2() async
    spawn girl_a02_at2();

    // 0233 moveVel(rad(90),2)；0234 moveVelTime(120,1,-11.25deg,3)；
    // 0236 moveVelTime(60,4,+11.25deg,4)。源镜像按角度 θ→180°-θ 显式换算（enmCreateM）。
    var a2: angle = 191.25deg;
    var a3: angle = 168.75deg;
    if mirror == 0 {
        a2 = -11.25deg;
        a3 = 11.25deg;
    }
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(120, a2, 3fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a3, 4fx, EASE_QUAD_OUT);
    // 0237-0241：goto wait(1000) 无限循环，源敌保持存活直到出界回收。
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // 0962：本入口开头 wait(50)
    wait(50);
    // 0963-0970：D=16 的 do-while，每轮同帧创建一对，之后 wait(15)
    var d: int = 16;
    while d > 0 {
        // 0966-0967：enmCreate(-140,-32,hp90,item1000,score1) / 镜像 +140
        _ = spawn_enemy(-140fx, -32fx, 90, 0, 0, 0, girl_a02(0));
        _ = spawn_enemy(140fx, -32fx, 90, 0, 0, 0, girl_a02(1));
        wait(15);
        d = d - 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
